                    top not in local
                    and top not in sys.stdlib_module_names
                    and top not in sys.builtin_module_names
                ):
                    raise PublisherClosureError(f"publisher has unlisted non-stdlib import: {top}")


def validate(value: Any) -> dict[str, Any]:
    keys = {
